/** @import { Effect, TemplateNode } from '#client' */
/** @import { Renderer } from '../../custom-renderer/types.js' */
/** @import { Batch } from '../../reactivity/batch.js' */
import { current_batch } from '../../reactivity/batch.js';
import {
	branch,
	destroy_effect,
	move_effect,
	pause_effect,
	resume_effect
} from '../../reactivity/effects.js';
import { HMR_ANCHOR } from '../../constants.js';
import { EFFECT_OFFSCREEN } from '#client/constants';
import { hydrate_node, hydrating } from '../hydration.js';
import {
	create_text,
	should_defer_append,
	create_fragment,
	append_child,
	insert_before,
	remove_node,
	get_last_child
} from '../operations.js';
import { DEV } from 'esm-env';
import { push_renderer, current_renderer, pop_renderer } from '../../custom-renderer/state.js';
import { custom_renderers_flag } from '../../../flags/index.js';

/**
 * @typedef {{ effect: Effect, fragment: DocumentFragment }} Branch
 */

/**
 * @template Key
 */
export class BranchManager {
	/** @type {TemplateNode} */
	anchor;

	/** @type {Map<Batch, Key>} */
	#batches = new Map();

	/**
	 * Map of keys to effects that are currently rendered in the DOM.
	 * These effects are visible and actively part of the document tree.
	 * Example:
	 * ```
	 * {#if condition}
	 * 	foo
	 * {:else}
	 * 	bar
	 * {/if}
	 * ```
	 * Can result in the entries `true->Effect` and `false->Effect`
	 * @type {Map<Key, Effect>}
	 */
	#onscreen = new Map();

	/**
	 * Similar to #onscreen with respect to the keys, but contains branches that are not yet
	 * in the DOM, because their insertion is deferred.
	 * @type {Map<Key, Branch>}
	 */
	#offscreen = new Map();

	/**
	 * Keys of effects that are currently outroing
	 * @type {Set<Key>}
	 */
	#outroing = new Set();

	/**
	 * Whether to pause (i.e. outro) on change, or destroy immediately.
	 * This is necessary for `<svelte:element>`
	 */
	#transition = true;

	/**
	 * The renderer that was active when this BranchManager was created.
	 * Needed so that #commit can push the correct renderer when doing DOM operations
	 * outside of an effect context (e.g. as a batch commit callback).
	 * @type {Renderer | null}
	 */
	#renderer = null;

	/**
	 * @param {TemplateNode} anchor
	 * @param {boolean} transition
	 */
	constructor(anchor, transition = true) {
		this.anchor = anchor;
		this.#transition = transition;
		this.#renderer = current_renderer;
	}

	/**
	 * @param {Batch} batch
	 */
	#commit = (batch) => {
		// if this batch was made obsolete, bail
		if (!this.#batches.has(batch)) return;

		var previous_renderer = custom_renderers_flag ? push_renderer(this.#renderer) : null;

		try {
			var key = /** @type {Key} */ (this.#batches.get(batch));

			var onscreen = this.#onscreen.get(key);

			if (onscreen) {
				// effect is already in the DOM — abort any current outro
				resume_effect(onscreen);
				this.#outroing.delete(key);
			} else {
				// effect is currently offscreen. put it in the DOM
				var offscreen = this.#offscreen.get(key);

				if (offscreen) {
					// effect could have been outro'ed before through a prior batch — resume if necessary
					resume_effect(offscreen.effect);
					this.#onscreen.set(key, offscreen.effect);
					this.#offscreen.delete(key);

					if (DEV) {
						// Tell hmr.js about the anchor it should use for updates,
						// since the initial one will be removed
						/** @type {any} */ (get_last_child(offscreen.fragment))[HMR_ANCHOR] = this.anchor;
					}

					// remove the anchor...
					remove_node(/** @type {ChildNode} */ (get_last_child(offscreen.fragment)));

					// ...and append the fragment
					insert_before(this.anchor, offscreen.fragment);
					onscreen = offscreen.effect;
					onscreen.f &= ~EFFECT_OFFSCREEN;
				}
			}

			// other batches can still commit (in any order), so their selections remain
			this.#discard(batch);

			// outro/destroy all onscreen effects...
			for (const [k, effect] of this.#onscreen) {
				// ...except the one that was just committed
				//    or those that are already outroing (else the transition is aborted and the effect destroyed right away)
				if (k === key || this.#outroing.has(k)) continue;

				const on_destroy = () => {
					const keys = Array.from(this.#batches.values());

					if (keys.includes(k)) {
						// keep the effect offscreen, as another batch will need it
						var fragment = create_fragment();
						move_effect(effect, fragment);

						append_child(fragment, create_text()); // TODO can we avoid this?

						this.#offscreen.set(k, { effect, fragment });
					} else {
						destroy_effect(effect);
					}

					this.#outroing.delete(k);
					this.#onscreen.delete(k);
				};

				if (this.#transition || !onscreen) {
					this.#outroing.add(k);
					pause_effect(effect, on_destroy, false);
				} else {
					on_destroy();
				}
			}
		} finally {
			if (custom_renderers_flag) pop_renderer(previous_renderer);
		}
	};

	/**
	 * @param {Batch} batch
	 */
	#discard = (batch) => {
		for (const b of this.#batches.keys()) {
			// (batches that were merged into another one don't select anything anymore)
			if (b === batch || !b.linked) this.#batches.delete(b);
		}

		const keys = Array.from(this.#batches.values());

		for (const [k, branch] of this.#offscreen) {
			if (!keys.includes(k)) {
				destroy_effect(branch.effect);
				this.#offscreen.delete(k);
			}
		}
	};

	/**
	 *
	 * @param {any} key
	 * @param {null | ((target: TemplateNode) => void)} fn
	 */
	ensure(key, fn) {
		var batch = /** @type {Batch} */ (current_batch);
		var defer = should_defer_append();

		if (fn && !this.#onscreen.has(key) && !this.#offscreen.has(key)) {
			if (defer) {
				var fragment = create_fragment();
				var target = create_text();

				append_child(fragment, target);

				var effect = branch(() => fn(target));

				// until it is committed, the branch only exists for the batches that select it
				effect.f |= EFFECT_OFFSCREEN;
				batch.unskip_new_effect(effect);

				this.#offscreen.set(key, { effect, fragment });
			} else {
				this.#onscreen.set(
					key,
					branch(() => fn(this.anchor))
				);
			}
		}

		this.#batches.set(batch, key);

		if (defer) {
			for (const [k, effect] of this.#onscreen) {
				if (k === key) {
					batch.unskip_effect(effect);
				} else {
					batch.skip_effect(effect);
				}
			}

			for (const [k, branch] of this.#offscreen) {
				if (k === key) {
					batch.unskip_effect(branch.effect);
				} else {
					batch.skip_effect(branch.effect);
				}
			}

			batch.oncommit(this.#commit);
			batch.ondiscard(this.#discard);
		} else {
			if (hydrating) {
				this.anchor = hydrate_node;
			}

			this.#commit(batch);
		}
	}
}
